            // Remove entries with greater 
            // keys with smaller or equal sums
            for (let i = sortedKeys.length - 1; i >= 0; i--) {
                const higher = sortedKeys[i];
                if (higher > val && dp.get(higher) <= currSum) {
                    dp.delete(higher);
                    sortedKeys.splice(i, 1);
                }
            }
        }

        ans = Math.max(ans, currSum);
    }

